const C = $('CONFIG').first().json;
const req = $json;
const body = req.body || {};
const fail = (status, errors) => [{ json: { valid: false, http_status: status, errors } }];

// 1. Optional shared-secret check (blank GATEWAY_AUTH_TOKEN = open gateway)
if (C.GATEWAY_AUTH_TOKEN && (req.headers || {})['x-gateway-token'] !== C.GATEWAY_AUTH_TOKEN) {
  return fail(401, ['unauthorized']);
}

// 2. CONFIG sanity (a broken config should say so, not fail mysteriously)
let providers;
try { providers = JSON.parse(C.PROVIDERS_JSON); } catch (err) { return fail(500, ['CONFIG.PROVIDERS_JSON is not valid JSON']); }
try { JSON.parse(C.STATE_API_HEADERS_JSON || '{}'); } catch (err) { return fail(500, ['CONFIG.STATE_API_HEADERS_JSON is not valid JSON']); }
for (const k of ['BREAKER_API_URL', 'RATE_LIMIT_API_URL', 'CACHE_API_URL']) {
  if (!/^https?:\/\//.test(C[k] || '')) return fail(500, [`CONFIG.${k} must start with http:// or https://`]);
}

// 2b. Gateway Rules sanity (a mistake in the rules node says so, before anything is called)
const R = $('Gateway Rules').first().json.rules;
{
  const isObj = (x) => x !== null && typeof x === 'object' && !Array.isArray(x);
  const rb = [];
  const add = (m) => rb.push('Rules: ' + m);
  const KNOWN = ['allowed_path_prefixes', 'allowed_params', 'blocked_params', 'max_staleness_seconds', 'remove_fields', 'use_cache', 'max_attempts', 'failure_threshold', 'cooldown_seconds'];
  const list = (x, max, f) => Array.isArray(x) && x.length <= max && x.every(f) && new Set(x).size === x.length;
  const checkEntry = (label, en) => {
    if (!isObj(en)) { add(`${label} must be an object`); return; }
    for (const k of Object.keys(en)) if (!KNOWN.includes(k)) add(`${label}.${k} is not a known setting (${KNOWN.join(', ')})`);
    if (en.allowed_path_prefixes !== undefined && !list(en.allowed_path_prefixes, 50, (x) => typeof x === 'string' && /^[A-Za-z0-9_.\/-]{1,200}$/.test(x) && !/\.\.|^\//.test(x))) add(`${label}.allowed_path_prefixes must be a list of at most 50 different path starts such as "items/" (no leading slash, no "..")`);
    for (const k of ['allowed_params', 'blocked_params']) if (en[k] !== undefined && !list(en[k], 50, (x) => typeof x === 'string' && /^[A-Za-z0-9_.\[\]-]{1,64}$/.test(x))) add(`${label}.${k} must be a list of at most 50 different parameter names`);
    if (en.max_staleness_seconds !== undefined && !(typeof en.max_staleness_seconds === 'number' && en.max_staleness_seconds >= 0 && en.max_staleness_seconds <= 1e7)) add(`${label}.max_staleness_seconds must be a number from 0 to 10000000`);
    if (en.remove_fields !== undefined && !list(en.remove_fields, 50, (x) => typeof x === 'string' && /^[A-Za-z0-9_]+(\.[A-Za-z0-9_]+){0,3}$/.test(x) && !/(^|\.)(__proto__|constructor|prototype)(\.|$)/.test(x))) add(`${label}.remove_fields must be a list of at most 50 different dotted field paths such as "user.ssn"`);
    if (en.use_cache !== undefined && typeof en.use_cache !== 'boolean') add(`${label}.use_cache must be true or false`);
    if (en.max_attempts !== undefined && !(Number.isInteger(en.max_attempts) && en.max_attempts >= 1 && en.max_attempts <= Number(C.MAX_ATTEMPTS))) add(`${label}.max_attempts must be a whole number from 1 to CONFIG.MAX_ATTEMPTS (${C.MAX_ATTEMPTS})`);
    if (en.failure_threshold !== undefined && !(Number.isInteger(en.failure_threshold) && en.failure_threshold >= 1 && en.failure_threshold <= Number(C.FAILURE_THRESHOLD))) add(`${label}.failure_threshold must be a whole number from 1 to CONFIG.FAILURE_THRESHOLD (${C.FAILURE_THRESHOLD})`);
    if (en.cooldown_seconds !== undefined && !(typeof en.cooldown_seconds === 'number' && en.cooldown_seconds >= Number(C.COOLDOWN_SECONDS) && en.cooldown_seconds <= Number(C.MAX_COOLDOWN_SECONDS))) add(`${label}.cooldown_seconds must be a number from CONFIG.COOLDOWN_SECONDS (${C.COOLDOWN_SECONDS}) to CONFIG.MAX_COOLDOWN_SECONDS (${C.MAX_COOLDOWN_SECONDS})`);
  };
  if (!R._is_obj) add('rules must be an object');
  else {
    for (const k of R._raw_keys) if (!['defaults', 'integrations'].includes(k)) add(`${k} is not a known setting (defaults, integrations)`);
    checkEntry('defaults', R.defaults);
    if (!isObj(R.integrations)) add('integrations must be an object');
    else for (const [name, en] of Object.entries(R.integrations)) {
      if (!Object.prototype.hasOwnProperty.call(providers, name)) add(`integrations.${name} is not defined in CONFIG.PROVIDERS_JSON`);
      checkEntry(`integrations.${name}`, en);
    }
  }
  if (rb.length) return fail(500, rb);
}

// 3. Request validation
const errors = [];
const integration = body.integration;
if (typeof integration !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(integration)) {
  errors.push('integration is required (letters, digits, - and _ only)');
} else if (!Object.prototype.hasOwnProperty.call(providers, integration)) {
  errors.push(`integration "${integration}" is not defined in CONFIG.PROVIDERS_JSON`);
} else {
  const p = providers[integration] || {};
  const rl = p.rate_limit || {};
  if (!/^https?:\/\//.test(p.base_url || '')) errors.push(`provider "${integration}" needs a base_url starting with http:// or https://`);
  if (!(rl.capacity > 0) || !(rl.refill_per_second > 0)) errors.push(`provider "${integration}" needs rate_limit.capacity and rate_limit.refill_per_second (positive numbers)`);
  if (errors.length) return fail(500, errors); // our config is wrong, not the caller
}

let resource_path = body.resource_path;
if (typeof resource_path !== 'string' || !resource_path.length) {
  errors.push('resource_path is required');
} else {
  resource_path = resource_path.replace(/^\/+/, '');
  if (/\.\.|:\/\/|[?#\\\s]/.test(resource_path)) errors.push('resource_path must be a plain path (no "..", "://", "?", "#", spaces or backslashes; pass query values in params)');
}
if (body.params !== undefined && (body.params === null || typeof body.params !== 'object' || Array.isArray(body.params))) errors.push('params must be an object');
if (typeof body.cache_key !== 'string' || !body.cache_key.length || body.cache_key.length > 200) errors.push('cache_key is required (string, max 200 characters)');
const ms = body.max_staleness_seconds;
if (ms !== undefined && ms !== null && !(typeof ms === 'number' && isFinite(ms) && ms >= 0)) errors.push('max_staleness_seconds must be a number >= 0');
const E = (typeof integration === 'string' && R.eff[integration]) || {};
if (E.allowed_path_prefixes && typeof resource_path === 'string' && !E.allowed_path_prefixes.some((p) => resource_path.startsWith(p))) errors.push(`resource_path is not allowed for integration "${integration}" (allowed prefixes: ${E.allowed_path_prefixes.join(', ')})`);
if (body.params && typeof body.params === 'object' && !Array.isArray(body.params)) {
  for (const k of Object.keys(body.params)) {
    if ((E.blocked_params || []).includes(k)) errors.push(`param "${k}" is not allowed for integration "${integration}"`);
    else if (E.allowed_params && !E.allowed_params.includes(k)) errors.push(`param "${k}" is not allowed for integration "${integration}" (allowed: ${E.allowed_params.join(', ')})`);
  }
}
if (errors.length) return fail(400, errors);

return [{ json: { valid: true, errors: [], http_status: 200,
  integration, resource_path, params: body.params || {},
  cache_key: integration + '__' + body.cache_key,   // namespaced so two integrations can never collide
  max_staleness_seconds: E.max_staleness_seconds === undefined ? (ms ?? null) : (ms == null ? E.max_staleness_seconds : Math.min(ms, E.max_staleness_seconds)) } }];

const t = $json;
const found = t.statusCode >= 200 && t.statusCode < 300;
const state = found ? (t.body || {}) : {};
const status = state.status || 'closed'; // closed | open
const now = Date.now();
let breaker_status;
if (status === 'closed') breaker_status = 'closed';
else if (now >= (state.next_probe_at || 0)) breaker_status = 'open_due_probe';
else breaker_status = 'open_no_probe';
return [{ json: { integration: t.integration, resource_path: t.resource_path, params: t.params,
  cache_key: t.cache_key, max_staleness_seconds: t.max_staleness_seconds,
  breaker_status, next_probe_at: state.next_probe_at || null, trip_count: state.trip_count || 0 } }];

const t = $json;
// The claim response (merged in by Merge Probe Claim + State) carries claim_token. Older state services do not send one.
const tok = (t.body && typeof t.body.claim_token === 'string' && t.body.claim_token.length > 0) ? t.body.claim_token : null;
const claim_warning = tok ? null : 'claim_token_missing: state service returned no claim_token, falling back to legacy probe behaviour (late probe results will NOT be rejected)';
if (!tok) console.warn('[gateway] WARNING ' + claim_warning + ' integration=' + t.integration);
return [{ json: { integration: t.integration, resource_path: t.resource_path, params: t.params, cache_key: t.cache_key, max_staleness_seconds: t.max_staleness_seconds, is_probe: true, attempt: 1, claim_token: tok, claim_warning } }];

const C = $('CONFIG').first().json;
const t = $json;
const body = (t.statusCode >= 200 && t.statusCode < 300) ? (t.body || {}) : {};
return [{ json: { integration: t.integration, cache_key: t.cache_key, max_staleness_seconds: t.max_staleness_seconds,
  degrade_reason: 'rate_limit_exhausted', retry_after_seconds: body.retry_after_seconds || C.DEGRADE_RETRY_AFTER_SECONDS } }];

const t = $json;
return [{ json: { integration: t.integration, cache_key: t.cache_key, max_staleness_seconds: t.max_staleness_seconds,
  degrade_reason: 'breaker_open', retry_after_seconds: Math.max(1, Math.round((t.next_probe_at - Date.now()) / 1000)) } }];

const C = $('CONFIG').first().json;
const t = $json;
return [{ json: { integration: t.integration, cache_key: t.cache_key, max_staleness_seconds: t.max_staleness_seconds, degrade_reason: 'probe_in_progress', retry_after_seconds: C.PROBE_IN_PROGRESS_RETRY_AFTER_SECONDS } }];

const t = $json;
return [{ json: { integration: t.integration, resource_path: t.resource_path, params: t.params, cache_key: t.cache_key,
  max_staleness_seconds: t.max_staleness_seconds, is_probe: t.is_probe, attempt: t.attempt,
  claim_token: t.claim_token || null, claim_warning: t.claim_warning || null,
  network_error: true, error_message: (t.error && t.error.message) || 'connection error', statusCode: null, body: null } }];

const t = $json;
let classification;
if (t.network_error) classification = 'transient';
else if (t.statusCode === 429) classification = 'rate_limited';
else if (t.statusCode >= 200 && t.statusCode < 300) classification = 'success';
else if (t.statusCode >= 500) classification = 'transient';
else classification = 'permanent'; // other 4xx -- our request is wrong, the provider is fine
return [{ json: { integration: t.integration, resource_path: t.resource_path, params: t.params, cache_key: t.cache_key,
  max_staleness_seconds: t.max_staleness_seconds, is_probe: t.is_probe, attempt: t.attempt,
  claim_token: t.claim_token || null, claim_warning: t.claim_warning || null,
  statusCode: t.statusCode, body: t.body, headers: t.headers || {}, classification } }];

const C = $('CONFIG').first().json;
const t = $json;
const raw = (t.headers && (t.headers['retry-after'] || t.headers['Retry-After'])) || null;
let secs = C.RETRY_AFTER_DEFAULT_SECONDS;               // used when the provider sent no usable header
if (raw) {
  const asInt = parseInt(raw, 10);
  if (!Number.isNaN(asInt) && String(asInt) === String(raw).trim()) secs = asInt;        // seconds form
  else { const d = new Date(raw); if (!isNaN(d.getTime())) secs = Math.max(1, Math.round((d.getTime() - Date.now()) / 1000)); } // HTTP-date form
}
return [{ json: { ...t, retry_after_seconds: Math.min(secs, C.RETRY_AFTER_CAP_SECONDS) } }];

const C = $('CONFIG').first().json;
const t = $json;
const backoff_ms = C.BACKOFF_BASE_MS * Math.pow(2, t.attempt - 1);
const jitter_ms = Math.floor(Math.random() * C.BACKOFF_JITTER_MS);
return [{ json: { ...t, wait_seconds: Math.round((backoff_ms + jitter_ms) / 100) / 10 } }];

const C = $('CONFIG').first().json;
const t = $json;
return [{ json: { integration: t.integration, cache_key: t.cache_key, max_staleness_seconds: t.max_staleness_seconds, degrade_reason: t.is_probe ? 'probe_failed' : 'transient_retries_exhausted', retry_after_seconds: C.DEGRADE_RETRY_AFTER_SECONDS, breaker_update: t.breaker_update || null } }];

const t = $json;
const E = ($('Gateway Rules').first().json.rules.eff || {})[t.integration] || {};
const paths = E.remove_fields || [];
const strip = (v, parts) => {
  if (Array.isArray(v)) return v.map((x) => strip(x, parts));
  if (v === null || typeof v !== 'object') return v;
  const [h, ...rest] = parts;
  const o = { ...v };
  if (rest.length === 0) delete o[h]; else if (h in o) o[h] = strip(o[h], rest);
  return o;
};
const found = t.statusCode >= 200 && t.statusCode < 300 && t.body && t.body.cached_at && E.use_cache !== false;
const age_seconds = found ? Math.round((Date.now() - t.body.cached_at) / 1000) : null;
const within_tolerance = t.max_staleness_seconds == null ? true : (age_seconds !== null && age_seconds <= t.max_staleness_seconds);
const usable = Boolean(found) && within_tolerance;
let cached_body = null;
if (found) { try { cached_body = JSON.parse(t.body.body); } catch (e) { cached_body = t.body.body; } }
if (found && cached_body !== null && typeof cached_body === 'object') for (const p of paths) cached_body = strip(cached_body, p.split('.'));   // entries cached before a rule existed
return [{ json: { usable, cached_body, age_seconds, degrade_reason: t.degrade_reason, retry_after_seconds: t.retry_after_seconds } }];

// ============================================================================
// GATEWAY RULES: the node for what is special about EACH API you front. DATA ONLY (no logic).
// Edit the values between the EDIT lines. Every request is checked against it, and a mistake gives a
// clear 500 (gateway_misconfigured, lines start "Rules:") before any service or provider is called.
// Rules can only make the gateway stricter or add plain data. What you cannot change here, on purpose:
// the circuit breaker, the single-probe claim, the rate limiter, the retry and Retry-After handling,
// the degrade-to-cache logic, and the CONFIG limits (a rule can lower them, never raise them).
// ============================================================================
// ---- EDIT FROM HERE ---------------------------------------------------------
const rules = {
  // Settings that apply to every integration unless that integration has its own value (see below).
  defaults: {},
  // One entry per integration name from CONFIG.PROVIDERS_JSON (an unknown name is refused). Each entry may set:
  //   allowed_path_prefixes: ['items/', 'orders/']   resource_path must start with one of these (400 otherwise)
  //   allowed_params: ['page', 'limit']              only these query parameter names are accepted
  //   blocked_params: ['api_key', 'token']           these query parameter names are refused
  //   max_staleness_seconds: 300                     oldest cached answer ever served; also the default when the caller sends none
  //   remove_fields: ['password', 'user.ssn']       dotted paths removed from every answer and from the cache (lists are handled item by item)
  //   use_cache: false                               never store or serve a cached copy for this integration
  //   max_attempts: 2                                tries per request, at most CONFIG.MAX_ATTEMPTS
  //   failure_threshold: 2                           failures that open the breaker, at most CONFIG.FAILURE_THRESHOLD
  //   cooldown_seconds: 120                          how long the breaker stays open, at least CONFIG.COOLDOWN_SECONDS
  // Example: { orders: { allowed_path_prefixes: ['orders/'], remove_fields: ['customer.email'], max_staleness_seconds: 300 } }
  integrations: {},
};
// ---- STOP EDITING HERE ------------------------------------------------------
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const pick = (o, k, d) => (o && o[k] !== undefined && o[k] !== null ? o[k] : d);
const defaults = pick(rules, 'defaults', {});
const integrations = pick(rules, 'integrations', {});
let names = [];
try { names = Object.keys(JSON.parse($('CONFIG').first().json.PROVIDERS_JSON)); } catch (e) { names = []; }   // a bad PROVIDERS_JSON is reported by Validate Request
const eff = {};                                                                                                // defaults + that integration's own values
for (const n of names) eff[n] = { ...(isObj(defaults) ? defaults : {}), ...(isObj(integrations) && isObj(integrations[n]) ? integrations[n] : {}) };
const norm = { defaults, integrations, eff, _is_obj: isObj(rules), _raw_keys: Object.keys(rules || {}) };
return [{ json: { ...$input.first().json, rules: norm } }];

const t = $json;
const E = ($('Gateway Rules').first().json.rules.eff || {})[t.integration] || {};
const paths = E.remove_fields || [];
const strip = (v, parts) => {
  if (Array.isArray(v)) return v.map((x) => strip(x, parts));
  if (v === null || typeof v !== 'object') return v;
  const [h, ...rest] = parts;
  const o = { ...v };
  if (rest.length === 0) delete o[h]; else if (h in o) o[h] = strip(o[h], rest);
  return o;
};
if (!paths.length || t.body === null || typeof t.body !== 'object') return [{ json: t }];
let body = t.body;
for (const p of paths) body = strip(body, p.split('.'));
return [{ json: { ...t, body } }];

const ctx = $('Apply Field Rules').first().json;
const r = $json || {};
let breaker_update;
if (r.accepted === false) breaker_update = 'ignored_stale_claim';
else if (r.error || (r.accepted === undefined && r.status === undefined)) breaker_update = 'record_failed';
else if (ctx.is_probe === true && !ctx.claim_token) breaker_update = 'applied_without_claim_token';
else breaker_update = 'applied';
if (breaker_update === 'ignored_stale_claim') console.warn('[gateway] ignored a late probe success for "' + ctx.integration + '": its claim was replaced');
return [{ json: { integration: ctx.integration, is_probe: ctx.is_probe === true, breaker_update, breaker_update_reason: r.reason || null, claim_warning: ctx.claim_warning || null } }];

const ctx = $('Classify Response').first().json;
const r = $json || {};
const ok2xx = r.statusCode >= 200 && r.statusCode < 300;
const b = (r.body && typeof r.body === 'object') ? r.body : {};
let breaker_update;
if (ok2xx && b.accepted === false) breaker_update = 'ignored_stale_claim';
else if (!ok2xx) breaker_update = 'record_failed';
else if (ctx.is_probe === true && !ctx.claim_token) breaker_update = 'applied_without_claim_token';
else breaker_update = 'applied';
if (breaker_update === 'ignored_stale_claim') console.warn('[gateway] ignored a late probe failure for "' + ctx.integration + '": its claim was replaced');
return [{ json: { breaker_update, breaker_update_reason: b.reason || null } }];
